 2	/**
 3	 * Port of dataset/bech32/test14.py.
 4	 *
 5	 * Reads a comma separated list of integers plus three bit widths, regroups the
 6	 * data from `--b` bit units into `--c` bit units, then again into `--d` bit
 7	 * units, and prints both intermediate results.
 8	 *
 9	 *   node test14.mjs --a 165,53,183,4,81,215 --b 8 --c 5 --d 8
10	 *
11	 * The original is shipped as a frozen executable, so its `sys.argv[0]` -- and
12	 * therefore the program name argparse prints -- is `test14_executable`.
13	 */
14	
15	import { ArgumentParser } from './lib/argparse/parser.mjs';
16	import { intType, strType } from './lib/argparse/types.mjs';
17	import * as bech32 from './lib/bech32/index.mjs';
18	import { frame, inFrame } from './lib/python/errors.mjs';
19	import { pyPrint } from './lib/python/io.mjs';
20	import { pyInt } from './lib/python/pyint.mjs';
21	import { runFrozenScript } from './lib/python/runtime.mjs';
22	
23	const SCRIPT_FILE = 'test14.py';
24	const SCRIPT_STEM = 'test14';
25	const PROG = 'test14_executable';
26	
27	/**
28	 * Frames of the original script.  The column offsets are those of the failing
29	 * expression on each line, which is what the caret line marks:
30	 *   line 12: `data = list(map(int, args.a.split(',')))`
31	 *   line 13: `step1 = bech32.convertbits(data, args.b, args.c)`
32	 *   line 14: `step2 = bech32.convertbits(step1, args.c, args.d)`
33	 *   line 19: `main()`
34	 */
35	const FRAMES = {
36	  module: frame({ file: SCRIPT_FILE, line: 19, func: '<module>', colno: 4, endColno: 10 }),
37	  parseData: frame({ file: SCRIPT_FILE, line: 12, func: 'main', colno: 11, endColno: 44 }),
38	  step1: frame({ file: SCRIPT_FILE, line: 13, func: 'main', colno: 12, endColno: 52 }),
39	  step2: frame({ file: SCRIPT_FILE, line: 14, func: 'main', colno: 12, endColno: 53 }),
40	};
41	
42	function main() {
43	  const parser = new ArgumentParser({ prog: PROG });
44	  parser.add_argument('--a', { type: strType, required: true }); // Data as comma-separated integers
45	  parser.add_argument('--b', { type: intType, required: true }); // From bits
46	  parser.add_argument('--c', { type: intType, required: true }); // Intermediate bits
47	  parser.add_argument('--d', { type: intType, required: true }); // To bits
48	  const args = parser.parse_args(process.argv.slice(2));
49	
50	  const data = inFrame(FRAMES.parseData, () => args.a.split(',').map((piece) => pyInt(piece)));
51	  // Convert from bits to intermediate bits
52	  const step1 = inFrame(FRAMES.step1, () => bech32.convertbits(data, args.b, args.c));
53	  // Convert from intermediate to final bits
54	  const step2 = inFrame(FRAMES.step2, () => bech32.convertbits(step1, args.c, args.d));
55	  pyPrint(step1);
56	  pyPrint(step2);
57	}
58	
59	runFrozenScript({ scriptStem: SCRIPT_STEM, moduleFrame: FRAMES.module, main });

